struct ListNode {
    int val;
    ListNode* next;
    ListNode(int v = 0, ListNode* n = nullptr) : val(v), next(n) {}
};

// Merge two sorted lists; 'tail' receives the last node of the result.
ListNode* mergeLists(ListNode* a, ListNode* b, ListNode*& tail) {
    ListNode dummy;
    ListNode* t = &dummy;
    while (a && b) {
        if (b->val < a->val) { t->next = b; b = b->next; }
        else                 { t->next = a; a = a->next; }   // stable
        t = t->next;
    }
    t->next = a ? a : b;
    while (t->next) t = t->next;
    tail = t;
    return dummy.next;
}

// Cut the first n nodes off 'head'; return what follows them.
ListNode* cut(ListNode* head, int n) {
    for (int i = 1; head && i < n; ++i) head = head->next;
    if (!head) return nullptr;
    ListNode* rest = head->next;
    head->next = nullptr;
    return rest;
}

// Bottom-up merge sort: O(n log n) time, O(1) extra space.
ListNode* sortList(ListNode* head) {
    int n = 0;
    for (ListNode* p = head; p; p = p->next) ++n;
    ListNode dummy(0, head);
    for (int width = 1; width < n; width *= 2) {
        ListNode* prev = &dummy;          // tail of the merged part
        ListNode* cur = dummy.next;
        while (cur) {
            ListNode* left = cur;
            ListNode* right = cut(left, width);
            cur = cut(right, width);
            ListNode* tail;
            prev->next = mergeLists(left, right, tail);
            prev = tail;
        }
    }
    return dummy.next;
}

