struct ListNode {
    int val;
    ListNode* next;
    ListNode(int v = 0, ListNode* n = nullptr) : val(v), next(n) {}
};

ListNode* insert(ListNode* head, int x) {
    ListNode* node = new ListNode(x);
    if (!head) {
        node->next = node;
        return node;
    }
    ListNode* prev = head;
    ListNode* cur = head->next;
    while (true) {
        if (prev->val <= x && x <= cur->val) break;           // fits in order
        if (prev->val > cur->val &&                           // max -> min seam
            (x >= prev->val || x <= cur->val)) break;         // new max or new min
        prev = cur;
        cur = cur->next;
        if (prev == head) break;     // full circle: all values equal, any spot works
    }
    prev->next = node;
    node->next = cur;
    return head;
}
